?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($title)?> — SmartToolz</title><meta name="description" content="<?=htmlspecialchars($title)?> online tool"><script src="https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js"></script><script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/qrcode@1.5.3/build/qrcode.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.js"></script><style>:root{--p:#635bff;--ink:#172033;--muted:#707b8e;--line:#e5e9f0;--bg:#f6f8fc}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,Arial,sans-serif}.page{width:min(1050px,calc(100% - 28px));margin:38px auto 70px}.hero,.box{background:#fff;border:1px solid var(--line);border-radius:22px;box-shadow:0 15px 45px rgba(25,35,70,.06)}.hero{padding:34px;margin-bottom:18px}.eyebrow{color:var(--p);font-size:11px;font-weight:900;letter-spacing:1px}.hero h1{font-size:clamp(32px,5vw,48px);letter-spacing:-2px;margin:8px 0}.hero p,.hint{color:var(--muted);line-height:1.65}.box{padding:25px}.box h2{margin:0 0 12px}.input,textarea,select{width:100%;border:1px solid #dfe4ec;border-radius:11px;padding:12px;background:#fff;outline:0;font:inherit;margin:6px 0 12px}textarea{min-height:190px;resize:vertical}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.btn{display:inline-block;border:0;border-radius:11px;padding:12px 17px;background:var(--p);color:#fff;font-weight:800;cursor:pointer}.btn.alt{background:#edf0f5;color:#263148}.buttons{display:flex;gap:8px;flex-wrap:wrap}.out{white-space:pre-wrap;word-break:break-word;background:#f7f8fb;border:1px solid var(--line);border-radius:12px;padding:15px;margin-top:14px;min-height:46px}.preview{display:block;max-width:100%;max-height:520px;margin:15px auto;border-radius:12px}.drop{border:2px dashed #d7dbee;border-radius:16px;padding:34px;text-align:center;color:var(--muted);cursor:pointer}.center{text-align:center}.ok{color:#118653;font-weight:700}@media(max-width:650px){.row{grid-template-columns:1fr}.hero,.box{padding:22px}}</style></head><body><?php require_once __DIR__.'/header.php'; ?><main class="page"><section class="hero"><div class="eyebrow">SMARTTOOLZ TOOL</div><h1><?=htmlspecialchars($title)?></h1><p>Fast, simple and browser-based. Your input is processed directly in your browser whenever possible.</p></section><section class="box" id="app"></section></main><?php require_once __DIR__.'/footer.php'; ?><script>
(function(){
'use strict';
var S=<?=json_encode($slug)?>,A=document.getElementById('app');
function q(s){return A.querySelector(s)}
function dl(blob,name){var a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(a.href)},1000)}
function fileBox(accept,multi){A.innerHTML='<h2>Select file'+(multi?'s':'')+'</h2><div class="drop" id="drop">Click here or drag & drop</div><input id="files" class="input" type="file" accept="'+accept+'" '+(multi?'multiple':'')+' hidden><div id="work"></div>';var d=q('#drop'),f=q('#files');d.onclick=function(){f.click()};d.ondragover=function(e){e.preventDefault()};d.ondrop=function(e){e.preventDefault();f.files=e.dataTransfer.files;f.dispatchEvent(new Event('change'))};return f}
function text(kind){A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES) ?></h2><textarea id="src" placeholder="Enter text..."></textarea><div class="buttons"><button class="btn" id="run">Process</button><button class="btn alt" id="copy">Copy</button></div><div class="out" id="out"></div>';q('#run').onclick=function(){var s=q('#src').value,o=s;if(kind==='word')o='Words: '+(s.trim()?s.trim().split(/\s+/).length:0)+'\nCharacters: '+s.length+'\nNo spaces: '+s.replace(/\s/g,'').length+'\nLines: '+(s?s.split(/\r?\n/).length:0);if(kind==='case')o=s.toUpperCase();if(kind==='dup')o=[...new Set(s.split(/\r?\n/))].join('\n');if(kind==='spaces')o=s.replace(/[ \t]+/g,' ').replace(/^ +| +$/gm,'');if(kind==='sort')o=s.split(/\r?\n/).sort(function(a,b){return a.localeCompare(b,undefined,{numeric:true,sensitivity:'base'})}).join('\n');if(kind==='reverse')o=[...s].reverse().join('');if(kind==='slug')o=s.toLowerCase().trim().replace(/[^a-z0-9\s-]/g,'').replace(/\s+/g,'-').replace(/-+/g,'-');if(kind==='markdown')o=s.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>').replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/\*(.*?)\*/g,'<em>$1</em>');q('#out').textContent=o};q('#copy').onclick=function(){if(navigator.clipboard)navigator.clipboard.writeText(q('#out').textContent)}}
function codec(kind){A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES) ?></h2><textarea id="src"></textarea><button class="btn" id="run">Process</button><textarea id="out" readonly></textarea>';q('#run').onclick=function(){var s=q('#src').value,o='';try{if(kind==='b64e')o=btoa(unescape(encodeURIComponent(s)));else if(kind==='b64d')o=decodeURIComponent(escape(atob(s)));else if(kind==='ue')o=encodeURIComponent(s);else if(kind==='ud')o=decodeURIComponent(s);else if(kind==='he')o=s.replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]});else{var t=document.createElement('textarea');t.innerHTML=s;o=t.value}q('#out').value=o}catch(e){q('#out').value='Invalid input: '+e.message}}}
function json(){A.innerHTML='<h2>JSON Formatter</h2><textarea id="src" placeholder="Paste JSON..."></textarea><button class="btn" id="run">Format & Validate</button><div class="out" id="out"></div>';q('#run').onclick=function(){try{q('#out').textContent=JSON.stringify(JSON.parse(q('#src').value),null,2)}catch(e){q('#out').textContent='Invalid JSON: '+e.message}}}
function gen(kind){if(kind==='password'){A.innerHTML='<h2>Password Generator</h2><input id="len" class="input" type="number" value="16" min="4" max="128"><button class="btn" id="run">Generate</button><div class="out" id="out"></div>';q('#run').onclick=function(){var c='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%^&*',s='';for(var i=0;i<+q('#len').value;i++)s+=c[Math.floor(Math.random()*c.length)];q('#out').textContent=s};return}if(kind==='uuid'){A.innerHTML='<h2>UUID Generator</h2><button class="btn" id="run">Generate</button><div class="out" id="out"></div>';q('#run').onclick=function(){q('#out').textContent=crypto.randomUUID()};return}if(kind==='random'){A.innerHTML='<h2>Random Number Generator</h2><div class="row"><input id="min" class="input" type="number" value="1"><input id="max" class="input" type="number" value="100"></div><button class="btn" id="run">Generate</button><div class="out" id="out"></div>';q('#run').onclick=function(){var a=+q('#min').value,b=+q('#max').value;q('#out').textContent=Math.floor(Math.random()*(b-a+1))+a};return}if(kind==='lorem'){A.innerHTML='<h2>Lorem Ipsum Generator</h2><input id="n" class="input" type="number" value="3" min="1" max="20"><button class="btn" id="run">Generate</button><textarea id="out"></textarea>';q('#run').onclick=function(){var p='Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.';q('#out').value=Array.from({length:+q('#n').value},function(){return p}).join('\n\n')};return}A.innerHTML='<h2>QR Code Generator</h2><input id="src" class="input" placeholder="Text or URL"><button class="btn" id="run">Create QR</button><div class="center"><canvas id="qr"></canvas></div>';q('#run').onclick=function(){QRCode.toCanvas(q('#qr'),q('#src').value||'SmartToolz',{width:280})}}
function calc(kind){var h='';if(kind==='age')h='<h2>Age Calculator</h2><input id="dob" class="input" type="date">';if(kind==='pct')h='<h2>Percentage Calculator</h2><div class="row"><input id="a" class="input" type="number" placeholder="Percentage"><input id="b" class="input" type="number" placeholder="Number"></div>';if(kind==='bmi')h='<h2>BMI Calculator</h2><div class="row"><input id="w" class="input" type="number" placeholder="Weight kg"><input id="hh" class="input" type="number" placeholder="Height cm"></div>';if(kind==='unit')h='<h2>Unit Converter</h2><input id="v" class="input" type="number" value="1"><div class="row"><select id="from"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select><select id="to"><option value="m">Meters</option><option value="km">Kilometers</option><option value="ft">Feet</option><option value="mi">Miles</option><option value="kg">Kilograms</option><option value="lb">Pounds</option></select></div>';A.innerHTML=h+'<button class="btn" id="run">Calculate</button><div class="out" id="out"></div>';q('#run').onclick=function(){var o='';if(kind==='age'){if(!q('#dob').value)return;o=(new Date().getFullYear()-new Date(q('#dob').value).getFullYear())+' years (approx.)'}else if(kind==='pct')o=((+q('#a').value*+q('#b').value)/100).toFixed(2);else if(kind==='bmi'){var x=+q('#hh').value/100;o=(+q('#w').value/(x*x)).toFixed(2)}else{var f={m:1,km:1000,ft:.3048,mi:1609.344,kg:1,lb:.453592};o=((+q('#v').value*f[q('#from').value])/f[q('#to').value]).toFixed(6)+' '+q('#to').value}q('#out').textContent=o}}
function image(kind){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image(),file=f.files[0];if(!file)return;im.onload=function(){A.querySelector('#work').innerHTML='<div class="row"><input id="w" class="input" type="number" value="'+im.width+'"><input id="h" class="input" type="number" value="'+im.height+'"></div><input id="q" class="input" type="number" value="0.9" min="0.1" max="1" step="0.1"><button class="btn" id="run">Process & Download</button><div class="out" id="out"></div>';q('#run').onclick=function(){var c=document.createElement('canvas'),w=+q('#w').value,h=+q('#h').value;c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);var mime=kind==='png'?'image/png':kind==='webp'?'image/webp':'image/jpeg',ext=kind==='png'?'png':kind==='webp'?'webp':'jpg';c.toBlob(function(b){dl(b,'smarttoolz.'+ext);q('#out').textContent='Done.'},mime,+q('#q').value||.9)}};im.src=URL.createObjectURL(file)}}
function transform(kind){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image();im.onload=function(){A.querySelector('#work').innerHTML='<div class="row"><input id="x" class="input" type="number" value="0"><input id="y" class="input" type="number" value="0"><input id="w" class="input" type="number" value="'+im.width+'"><input id="h" class="input" type="number" value="'+im.height+'"></div><button class="btn" id="run">Apply & Download</button><div class="out" id="out"></div>';q('#run').onclick=function(){var c=document.createElement('canvas'),x=c.getContext('2d'),w=+q('#w').value,h=+q('#h').value;c.width=w;c.height=h;if(kind==='crop')x.drawImage(im,+q('#x').value,+q('#y').value,w,h,0,0,w,h);else{x.save();if(kind==='flip'){x.scale(-1,1);x.drawImage(im,-w,0,w,h)}else{x.translate(w/2,h/2);x.rotate(Math.PI/2);x.drawImage(im,-h/2,-w/2,h,w)}x.restore()}c.toBlob(function(b){dl(b,kind+'.png');q('#out').textContent='Done.'},'image/png')}};im.src=URL.createObjectURL(f.files[0])}}
function color(){A.innerHTML='<h2>Color Converter / Picker</h2><input id="c" type="color" value="#635bff"><input id="hex" class="input" value="#635bff"><button class="btn" id="run">Convert</button><div class="out" id="out"></div>';q('#run').onclick=function(){var h=q('#hex').value;if(!/^#[0-9a-f]{6}$/i.test(h))h=q('#c').value;var n=parseInt(h.slice(1),16),r=n>>16&255,g=n>>8&255,b=n&255;q('#out').textContent='HEX: '+h.toUpperCase()+'\nRGB: '+r+', '+g+', '+b}}
function pdf(kind){var f=fileBox('application/pdf',kind==='merge');f.onchange=function(){A.querySelector('#work').innerHTML='<button class="btn" id="run">Process PDF</button><div class="out" id="out"></div>';q('#run').onclick=async function(){try{var fs=[...f.files];if(kind==='merge'){var out=await PDFLib.PDFDocument.create();for(var file of fs){var src=await PDFLib.PDFDocument.load(await file.arrayBuffer());(await out.copyPages(src,src.getPageIndices())).forEach(function(p){out.addPage(p)})}dl(new Blob([await out.save()],{type:'application/pdf'}),'merged.pdf')}else if(kind==='split'){var src=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());for(var i=0;i<src.getPageCount();i++){var one=await PDFLib.PDFDocument.create();one.addPage((await one.copyPages(src,[i]))[0]);dl(new Blob([await one.save()],{type:'application/pdf'}),'page-'+(i+1)+'.pdf')}}else{var src2=await PDFLib.PDFDocument.load(await fs[0].arrayBuffer());dl(new Blob([await src2.save()],{type:'application/pdf'}),'optimized.pdf')}q('#out').textContent='Done.'}catch(e){q('#out').textContent='Error: '+e.message}}}}
function pdfImg(fmt){var f=fileBox('application/pdf',false);f.onchange=function(){A.querySelector('#work').innerHTML='<button class="btn" id="run">Convert</button><div class="out" id="out"></div>';q('#run').onclick=async function(){try{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';var p=await pdfjsLib.getDocument({data:await f.files[0].arrayBuffer()}).promise,z=new JSZip();for(var i=1;i<=p.numPages;i++){var pg=await p.getPage(i),v=pg.getViewport({scale:2}),c=document.createElement('canvas');c.width=v.width;c.height=v.height;await pg.render({canvasContext:c.getContext('2d'),viewport:v}).promise;var b=await new Promise(function(r){c.toBlob(r,'image/'+fmt)});z.file('page-'+i+'.'+fmt,await b.arrayBuffer())}dl(await z.generateAsync({type:'blob'}),'pdf-'+fmt+'.zip');q('#out').textContent='Done.'}catch(e){q('#out').textContent='Error: '+e.message}}}}
function imgPdf(){var f=fileBox('image/png,image/jpeg',true);f.onchange=function(){A.querySelector('#work').innerHTML='<button class="btn" id="run">Create PDF</button><div class="out" id="out"></div>';q('#run').onclick=async function(){var doc=new jspdf.jsPDF();for(var i=0;i<f.files.length;i++){if(i)doc.addPage();var u=URL.createObjectURL(f.files[i]);await new Promise(function(ok){var im=new Image();im.onload=function(){var w=190,h=w*im.height/im.width;doc.addImage(im,'JPEG',10,10,w,h);URL.revokeObjectURL(u);ok()};im.src=u})}doc.save('images.pdf');q('#out').textContent='PDF created.'}}}
function txtPdf(){A.innerHTML='<h2>Text to PDF</h2><textarea id="src"></textarea><button class="btn" id="run">Create PDF</button>';q('#run').onclick=function(){var doc=new jspdf.jsPDF();doc.text(doc.splitTextToSize(q('#src').value,180),15,20);doc.save('text.pdf')}}
function qrRead(){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image();im.onload=function(){var c=document.createElement('canvas');c.width=im.width;c.height=im.height;c.getContext('2d').drawImage(im,0,0);var d=c.getContext('2d').getImageData(0,0,c.width,c.height),r=jsQR(d.data,d.width,d.height);A.querySelector('#work').innerHTML='<div class="out">'+(r?r.data:'No QR code detected.')+'</div>'};im.src=URL.createObjectURL(f.files[0])}}
function meme(){var f=fileBox('image/*',false);f.onchange=function(){var im=new Image();im.onload=function(){A.querySelector('#work').innerHTML='<input id="top" class="input" placeholder="Top text"><input id="bottom" class="input" placeholder="Bottom text"><button class="btn" id="run">Create Meme</button><canvas id="cv" class="preview"></canvas>';q('#run').onclick=function(){var c=q('#cv'),x=c.getContext('2d');c.width=im.width;c.height=im.height;x.drawImage(im,0,0);x.font=Math.max(24,im.width/12)+'px Impact';x.textAlign='center';x.lineWidth=5;x.strokeStyle='#000';x.fillStyle='#fff';[['top',50],['bottom',im.height-30]].forEach(function(a){var t=q('#'+a[0]).value;if(t){x.strokeText(t,c.width/2,a[1]);x.fillText(t,c.width/2,a[1])}});c.toBlob(function(b){dl(b,'meme.png')},'image/png')}};im.src=URL.createObjectURL(f.files[0])}}
function run(){var m={'image-compressor':function(){image('compress')},'image-resizer':function(){image('resize')},'jpg-to-png':function(){image('png')},'png-to-jpg':function(){image('jpg')},'webp-to-jpg':function(){image('jpg')},'jpg-to-webp':function(){image('webp')},'png-to-webp':function(){image('webp')},'gif-to-jpg':function(){image('jpg')},'image-cropper':function(){transform('crop')},'image-rotator':function(){transform('rotate')},'image-flipper':function(){transform('flip')},'word-counter':function(){text('word')},'case-converter':function(){text('case')},'remove-duplicate-lines':function(){text('dup')},'remove-extra-spaces':function(){text('spaces')},'sort-lines':function(){text('sort')},'reverse-text':function(){text('reverse')},'text-to-slug':function(){text('slug')},'markdown-to-html':function(){text('markdown')},'base64-encoder':function(){codec('b64e')},'base64-decoder':function(){codec('b64d')},'url-encoder':function(){codec('ue')},'url-decoder':function(){codec('ud')},'html-encoder':function(){codec('he')},'html-decoder':function(){codec('hd')},'json-formatter':json,'password-generator':function(){gen('password')},'uuid-generator':function(){gen('uuid')},'random-number-generator':function(){gen('random')},'lorem-ipsum-generator':function(){gen('lorem')},'qr-generator':function(){gen('qr')},'color-picker':color,'color-converter':color,'age-calculator':function(){calc('age')},'percentage-calculator':function(){calc('pct')},'bmi-calculator':function(){calc('bmi')},'unit-converter':function(){calc('unit')},'pdf-merger':function(){pdf('merge')},'pdf-splitter':function(){pdf('split')},'pdf-compressor':function(){pdf('compress')},'pdf-to-jpg':function(){pdfImg('jpeg')},'pdf-to-png':function(){pdfImg('png')},'png-to-pdf':imgPdf,'text-to-pdf':txtPdf,'qr-reader':qrRead,'meme-generator':meme};if(m[S])m[S]();else A.innerHTML='<h2><?=htmlspecialchars($title,ENT_QUOTES)?></h2><p class="hint">This tool is listed in SmartToolz.</p><a class="btn" href="/smart-toolz/t